import { test, expect } from '@playwright/test';

test.describe('Column Visibility Toggle', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table-list');
  });

  test('should toggle column visibility from settings menu', async ({ page }) => {
    // Verify table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify initial columns are visible
    const nameCol = page.getByRole('columnheader', { name: 'Name' });
    const emailCol = page.getByRole('columnheader', { name: 'Email' });
    const phoneCol = page.getByRole('columnheader', { name: 'Phone' });
    await expect(nameCol).toBeVisible();
    await expect(emailCol).toBeVisible();
    await expect(phoneCol).toBeVisible();

    // Open settings menu
    const settingsButton = page.getByRole('button', { name: 'Settings' });
    await settingsButton.click();

    // Verify settings menu is open
    const settingsMenu = page.getByRole('menu');
    await expect(settingsMenu).toBeVisible();

    // Toggle Phone column visibility
    const phoneToggle = page.getByRole('checkbox', { name: 'Phone' });
    await phoneToggle.click();

    // Verify Phone column is hidden
    await expect(phoneCol).not.toBeVisible();

    // Verify other columns are still visible
    await expect(nameCol).toBeVisible();
    await expect(emailCol).toBeVisible();

    // Close settings menu
    const closeButton = page.getByRole('button', { name: 'Close' });
    await closeButton.click();

    // Verify settings menu is closed
    await expect(settingsMenu).not.toBeVisible();

    // Verify Phone column is still hidden
    await expect(phoneCol).not.toBeVisible();
  });

  test('should restore column visibility when toggling back', async ({ page }) => {
    // Open settings menu
    const settingsButton = page.getByRole('button', { name: 'Settings' });
    await settingsButton.click();

    // Toggle Phone column visibility to hide it
    const phoneToggle = page.getByRole('checkbox', { name: 'Phone' });
    await phoneToggle.click();

    // Verify Phone column is hidden
    const phoneCol = page.getByRole('columnheader', { name: 'Phone' });
    await expect(phoneCol).not.toBeVisible();

    // Close settings menu
    const closeButton = page.getByRole('button', { name: 'Close' });
    await closeButton.click();

    // Reopen settings menu
    await settingsButton.click();

    // Toggle Phone column visibility back to show it
    await phoneToggle.click();

    // Verify Phone column is visible again
    await expect(phoneCol).toBeVisible();

    // Close settings menu
    await closeButton.click();

    // Verify settings menu is closed
    await expect(page.getByRole('menu')).not.toBeVisible();
  });
});
